function CashFeedbackDialog:ReUpdateUI()
    local todayHasDrawnLevelRebate = checkNumber(self.data.todayHasDrawnLevelRebate)
    local hasDrawnPayRebate = checkNumber(self.data.hasDrawnPayRebate)
    if checkNumber(self.data.levelRebateNum) == 0 then
        ---都领取过了
        todayHasDrawnLevelRebate = 1
    end
    if checkNumber(self.data.payRebateNum) == 0 then
        hasDrawnPayRebate = 1
    end
    if hasDrawnPayRebate == 1 and todayHasDrawnLevelRebate == 1 then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainVeteran, 0)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.MainVeteran)
    end
    if checkNumber(self.data.totalLevelRebateTimes) - checkNumber(self.data.hasDrawnLevelRebateTimes) <= 0 and checkNumber(self.data.hasDrawnPayRebate) == 1 then
        ---需要关闭界面
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        playerComponent.playerDojo.isVeteran = 0
        ---@type Engine.UI.UILuaDialog
        local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIHomeView)
        if dialog and dialog.Env then
            ---@type UIHomeMain
            local env = dialog.Env
            local mainlandBackRewardTrans = env.PlayerNode.transform.parent:Find("BtnTopRoot/BtnRegressionReward")
            if mainlandBackRewardTrans then
                CfUtils.SetActive(mainlandBackRewardTrans, checkNumber(playerComponent.playerDojo.isVeteran) == 1)
            end
        end
        ---关闭当前页面
        self:FreshUI(self.data)
    else
        GameUtils.Request("Veteran/rebateInfo", {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local data = checkTable(response.data)
                self.data = data
                self:FreshUI(self.data)
            end
        end)
    end
end

function CashFeedbackDialog:FreshUI(data)
    CfUtils.FillText(self.PlayerTxtName, data.playerName)
    CfUtils.FillText(self.LvTxtName, data.playerLevel)
    CfUtils.FillText(self.MoneyTxtName, data.amount)
    --CfUtils.FillText(self.TotalTxtNum, data.rebateNum)
    CfUtils.FillText(self.HavedTxtNum, data.payRebateNum)
    CfUtils.FillText(self.DayTxtNum, data.levelRebateNum)

    local dayTrans = self.DayTxtNum.transform.parent:Find("Day")
    if dayTrans then
        CfUtils.FillText(dayTrans:Find("HadGet/TxtDayNum"), self.data.hasDrawnLevelRebateTimes)
        CfUtils.FillText(dayTrans:Find("AllGet/TxtDayNum"), checkNumber(self.data.totalLevelRebateTimes) - checkNumber(self.data.hasDrawnLevelRebateTimes))
    end

    if checkNumber(data.levelRebateNum) == 0 or checkNumber(data.totalLevelRebateTimes) - checkNumber(data.hasDrawnLevelRebateTimes) <= 0 then
        CfUtils.SetActive(self.FontStyleButton, false)
    else
        CfUtils.SetActive(self.FontStyleButton,  (checkNumber(data.totalLevelRebateTimes) - checkNumber(data.hasDrawnLevelRebateTimes) > 0))
        local fontStyleBtn = self.FontStyleButton:GetComponent(typeof(FontStyleButton))
        fontStyleBtn:ResetFontStyle(checkNumber(self.data.todayHasDrawnLevelRebate) == 0 and "B25" or "B18", checkNumber(self.data.todayHasDrawnLevelRebate) == 1 and localize("已领取") or localize("领取"))
    end

    if checkNumber(data.payRebateNum) == 0 then
        ---左则累计回kui为0
        CfUtils.SetActive(self.BtnRecharge, false)
    else
        local fontStyleBtn2 = self.BtnRecharge:GetComponent(typeof(FontStyleButton))
        fontStyleBtn2:ResetFontStyle(checkNumber(self.data.hasDrawnPayRebate) == 0 and "B25" or "B18", checkNumber(self.data.hasDrawnPayRebate) == 1 and localize("已领取") or localize("领取"))
    end

end

function CashFeedbackDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isSuccess = false
        GameUtils.Request("Veteran/rebateInfo", {}, function(request, response)
            isSuccess = true
            if checkNumber(response.errCode) == 0 then
                self.data = checkTable(response.data)
                self:FreshUI(self.data)
            end
        end)
        while not isSuccess do
            coroutine.yield()
        end
    end))
    return coWait
end

function CashFeedbackDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CashFeedbackDialog